<script setup>
import {ref} from 'vue';import {useAuth} from '../stores/auth.js';import {useFood} from '../stores/food.js';import {demo} from '../services/api.js';import {money,useTask} from '../composables/useTask.js';const auth=useAuth(),food=useFood();const empty=()=>({name:'',price:0,category:'Rice',description:'',emoji:'🍽️',image_url:''});const edit=ref(empty());const {busy,error,run}=useTask();function save(){run(async()=>{await food.save(edit.value);edit.value=empty()})}
</script><template><h2>Food management</h2><p v-if="demo">Demo admin tools are available to everyone; Laravel must enforce admin privileges later.</p><p v-if="error" role="alert">{{error}}</p><template v-if="demo||auth.me?.user?.role==='admin'"><form class="panel" @submit.prevent="save"><h3>{{edit.id?'Edit food':'Add food'}}</h3><label>Name<input v-model="edit.name" required></label><label>Price<input v-model.number="edit.price" type="number" min="0.01" step="0.01" required></label><label>Category<input v-model="edit.category" required></label><label>Description<input v-model="edit.description"></label><label>Image URL (optional)<input v-model="edit.image_url" type="url"></label><button class="primary" :disabled="busy">Save</button> <button type="button" @click="edit=empty()">Clear</button></form><div class="panel" v-for="f in food.foods" :key="f.id"><div class="line"><b>{{f.name}} · {{money(f.price)}}</b><div><button @click="edit={...f}">Edit</button> <button :disabled="busy" @click="run(()=>food.remove(f.id))">Delete</button></div></div></div></template><p v-else>Admin access required.</p></template>
